pixels = im.load()
dark = []
for y in range(h):
    for x in range(w):
        p = pixels[x,y]
        if isinstance(p, int):
            r=g=b=p
        else:
            r,g,b = p[:3]
        if r<40 and g<40 and b<40:
            dark.append((x,y,r,g,b))
print("dark count", len(dark))
if dark:
    xs = [d[0] for d in dark]; ys=[d[1] for d in dark]
    print("bbox", min(xs), min(ys), max(xs), max(ys))
    print("centroid", sum(xs)/len(xs), sum(ys)/len(ys))
print("center", w/2, h/2)
# sample some pixels
for y in range(0,h,40):
    row = []
    for x in range(0,w,40):
        row.append(pixels[x,y][:3] if not isinstance(pixels[x,y], int) else pixels[x,y])
    print(y, row)
